"""Independent slow reference implementation straight from the task text."""
import itertools, json
from math import gcd
from fractions import Fraction

def parse_addr_slow(s):
    import ipaddress
    a = ipaddress.IPv6Address(s)
    if '%' in s: raise ValueError
    if '.' in s: raise ValueError
    return int(a)

def trunc(v, d):
    if d == 0: return 0
    return (v >> (128 - d)) << (128 - d)

def fmt(v):
    g = [(v >> sh) & 0xffff for sh in range(112, -1, -16)]
    best = None
    i = 0
    while i < 8:
        if g[i] == 0:
            j = i
            while j < 8 and g[j] == 0: j += 1
            if j - i >= 2 and (best is None or j - i > best[1]): best = (i, j - i)
            i = j
        else: i += 1
    if best is None:
        return ':'.join('%x' % x for x in g)
    i, l = best
    left = ':'.join('%x' % x for x in g[:i])
    right = ':'.join('%x' % x for x in g[i + l:])
    if left and right: return left + '::' + right
    if left: return left + '::'
    if right: return '::' + right
    return '::'

def al(k, x):
    return k * ((x + k - 1) // k) if x > 0 else 0

def spec_nodes(fib, cuts):
    """fib: list of (net,len,hop).  Returns stages in spec form."""
    S = len(cuts) - 1
    stages = []
    for i in range(S):
        b = cuts[i]; e = cuts[i + 1]
        if i == 0:
            prefices = [0]
        else:
            s = set()
            for (net, L, h) in fib:
                if L > b: s.add(trunc(net, b))
            prefices = sorted(s)
        nodes = []
        for q in prefices:
            rules = []
            if i == 0:
                for (net, L, h) in fib:
                    if L == 0: rules.append((0, net, h))
            for (net, L, h) in fib:
                if b < L <= e and trunc(net, b) == q:
                    rules.append((L, net, h))
            rules.sort()
            edges = []
            if e < 128:
                s = set()
                for (net, L, h) in fib:
                    if L > b and trunc(net, b) == q and L > e:
                        s.add(trunc(net, e))
                edges = sorted(s)
            nodes.append({'prefix': fmt(q) + '/%d' % b, 'rules': [
                {'prefix': fmt(net) + '/%d' % L, 'hop': h} for (L, net, h) in rules],
                'edges': [{'prefix': fmt(x) + '/%d' % e, 'child': None} for x in edges]})
        stages.append({'nodes': nodes})
    # fill child indices
    for i in range(S - 1):
        e = cuts[i + 1]
        pos = {}
        for j, nd in enumerate(stages[i + 1]['nodes']):
            pos[int(nd['prefix'].split('/')[0], 16) if False else nd['prefix'].rsplit('/',1)[0]] = j
        for nd in stages[i]['nodes']:
            for edg in nd['edges']:
                edg['child'] = pos[edg['prefix'].rsplit('/',1)[0]]
    used = []
    for i in range(S):
        b = cuts[i]; e = cuts[i + 1]
        u = 0
        for nd in stages[i]['nodes']:
            inner = 128
            for r in nd['rules']:
                L = int(r['prefix'].rsplit('/',1)[1])
                inner += 32 + al(8, L - b)
            inner += len(nd['edges']) * (32 + al(8, e - b))
            u += al(64, inner)
        used.append(u)
    return stages, used

def spec_peak(used, caps):
    best = Fraction(0)
    for u, c in zip(used, caps):
        best = max(best, Fraction(u, c))
    return best

def brute_opt(fib, caps, max_stride):
    """Enumerate all cut sequences; return (best peak, list of optimal cuts)."""
    S = len(caps)
    best = None
    bestcuts = []
    def rec(prefix, depth, remaining):
        nonlocal best, bestcuts
        if depth == S:
            if remaining == 0:
                cuts = list(prefix)
                stages, used = spec_nodes(fib, cuts)
                p = spec_peak(used, caps)
                if best is None or p < best:
                    best = p; bestcuts = [cuts]
                elif p == best:
                    bestcuts.append(cuts)
            return
        lo = 1
        for g in range(lo, min(max_stride, remaining - (S - depth - 1)) + 1):
            prefix.append(prefix[-1] + g)
            rec(prefix, depth + 1, remaining - g)
            prefix.pop()
    rec([0], 0, 128)
    return best, bestcuts

def lpm(fib, addr):
    bl = -1; bh = None
    for (net, L, h) in fib:
        if L > bl and (addr >> (128 - L) if L else 0) == (net >> (128 - L) if L else 0):
            bl = L; bh = h
    return (bh, bl)
